import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Diagrams","description":"","frontmatter":{"title":"Diagrams","covers":{"screens":["SCR-067"],"stories":["US-074"]}},"headers":[],"relativePath":"usage/diagrams.md","filePath":"usage/diagrams.md"}`),a={name:`usage/diagrams.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="diagrams" tabindex="-1">Diagrams <a class="header-anchor" href="#diagrams" aria-label="Permalink to “Diagrams”">​</a></h1><p>A diagram models a business process or another view of the architecture with the notation of a <a href="./../administration/metamodel-editing#viewpoints">viewpoint</a>, for example <em>Process Model (BPMN 2.0)</em>. This version of OEA manages diagrams as objects: you create, find, rename, delete and restore them. The canvas on which you place elements follows in a later version; until then, the page of a diagram shows its name, description and viewpoint.</p><p>You need the permission <code>entity:read</code> (for example the role <code>viewer</code>) to see diagrams. Creating, renaming and deleting needs <code>entity:write</code>, restoring <code>entity:restore</code> (role <code>enterprise-architect</code>). Service accounts with <code>entity:write</code> can create and change diagrams through the API like persons.</p><h2 id="find-diagrams" tabindex="-1">Find diagrams <a class="header-anchor" href="#find-diagrams" aria-label="Permalink to “Find diagrams”">​</a></h2><p>You find diagrams in three places:</p><ul><li><strong>The page <em>Diagrams</em>:</strong> choose <em>Diagrams</em> in the header. The page lists the diagrams by name, regardless of upper and lower case, each with its viewpoint, the notation of the viewpoint and the time of the last change. Type a part of a name into <em>Filter by name</em> to narrow the list; characters such as <code>%</code> and <code>_</code> are matched as typed. The list shows 50 diagrams at a time; choose <em>Load more</em> for the next ones. Without any diagram the page says <em>No diagrams yet.</em></li><li><strong>The browser:</strong> the category <em>Diagrams</em> of <em>Current state</em> in the sidebar lists the diagrams with the notation as a small label (see <a href="./navigation#browser">Navigation tree</a>).</li><li><strong>The navigation tree:</strong> diagrams that were placed in a folder (see <a href="./navigation#place-a-diagram">Place a diagram</a>).</li></ul><p>Choose a diagram to open its page.</p><h2 id="create-a-diagram" tabindex="-1">Create a diagram <a class="header-anchor" href="#create-a-diagram" aria-label="Permalink to “Create a diagram”">​</a></h2><ol><li><p>Choose <em>Create diagram</em> on the page <em>Diagrams</em>.</p></li><li><p>Fill in the dialog:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>Name</td><td>required, 1 to 200 characters; unique among the diagrams, regardless of upper and lower case; surrounding blanks are removed</td></tr><tr><td>Description</td><td>optional, up to 2000 characters</td></tr><tr><td>Viewpoint</td><td>required; the viewpoint of the diagram and its notation</td></tr></tbody></table></li><li><p>Choose <em>Create</em>. The new, empty diagram opens.</p></li></ol><p>The viewpoint is fixed when you create the diagram and cannot be changed later. If the name is taken, the dialog says <em>A diagram with this name already exists.</em></p><h2 id="rename-and-delete-a-diagram" tabindex="-1">Rename and delete a diagram <a class="header-anchor" href="#rename-and-delete-a-diagram" aria-label="Permalink to “Rename and delete a diagram”">​</a></h2><p><em>Rename</em> changes the name and the description of a diagram, on the page <em>Diagrams</em> and on the page of the diagram. If someone else changed the diagram meanwhile, the dialog says so; reload the page and repeat your change.</p><p><em>Delete</em> asks for a confirmation. A deleted diagram no longer appears in the list, the browser and the navigation tree, and its name can be used again. <strong>The entities of the repository stay.</strong> The diagram itself can be restored (see below).</p><h2 id="restore-a-diagram" tabindex="-1">Restore a diagram <a class="header-anchor" href="#restore-a-diagram" aria-label="Permalink to “Restore a diagram”">​</a></h2><p>With the permission <code>entity:restore</code>, the switch <em>Show deleted</em> on the page <em>Diagrams</em> lists the deleted diagrams with the time and the person of the deletion. Choose <em>Restore</em> to bring a diagram back, together with its entries in the navigation tree. If another diagram has taken its name meanwhile, the page says so and the diagram stays deleted; rename the other diagram first.</p><h2 id="deleting-a-viewpoint" tabindex="-1">Deleting a viewpoint <a class="header-anchor" href="#deleting-a-viewpoint" aria-label="Permalink to “Deleting a viewpoint”">​</a></h2><p>Diagrams cannot exist without their viewpoint. When you delete a viewpoint that diagrams use, they are deleted with it, <strong>for good</strong> and including the deleted ones; the entities stay. The confirmation names the number of diagrams that will be deleted (see <a href="./../administration/metamodel-editing#viewpoints">Viewpoints</a>). The same happens when a new version of a <a href="./../administration/metamodel-packages">metamodel package</a> no longer carries a system-defined viewpoint.</p><h2 id="through-the-api" tabindex="-1">Through the API <a class="header-anchor" href="#through-the-api" aria-label="Permalink to “Through the API”">​</a></h2><p>The diagrams are available through <code>/diagrams</code> (see the <a href="./../api/">API reference</a>):</p><ul><li><code>GET /diagrams</code> lists the diagrams by name. <code>q</code> is a part of the name (at most 200 characters), <code>pageSize</code> is 1 to 200 (default 50), and <code>page</code> starts at 0. The answer carries <code>nextCursor</code>; send it as <code>cursor</code> together with <code>page</code> increased by 1 to continue. A cursor of another query is rejected with 400 naming <code>cursor</code>.</li><li><code>POST /diagrams</code> creates a diagram from <code>name</code>, <code>description</code> and <code>viewpointId</code>; <code>GET /diagrams/{id}</code> reads it; <code>PUT /diagrams/{id}</code> changes <code>name</code> and <code>description</code> (a <code>viewpointId</code> is ignored); <code>DELETE /diagrams/{id}</code> deletes it. Every change needs the header <code>If-Match</code> with the version that was read (<code>&quot;3&quot;</code>); without it the answer is 428, with another version 412. The answers carry the new version as <code>ETag</code>.</li><li><code>GET /diagrams/deleted</code> lists the deleted diagrams, and <code>POST /diagrams/{id}/restore</code> with <code>If-Match</code> restores one; both need <code>entity:restore</code>. A diagram that is not deleted answers 409 (<code>urn:oea:problem:diagram-not-deleted</code>).</li><li>A taken name answers 422 with the problem type <code>urn:oea:problem:diagram-name-taken</code>; other invalid input answers 422 and names the field in <code>invalidFields</code> (<code>name</code>, <code>description</code> or <code>viewpointId</code>). An unknown or deleted diagram answers 404.</li><li>Every change is recorded in the audit trail as <code>diagram.created</code>, <code>diagram.updated</code>, <code>diagram.deleted</code> or <code>diagram.restored</code>.</li></ul>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};